import subprocess
c='p5';B='JS CƠ BẢN'
def JS(code):
    r=subprocess.run(['node','-e',code],capture_output=True,text=True,timeout=10)
    return (r.stdout+r.stderr).rstrip('\n')
def JR(c_,code,tag,title,note='',fs=22,show=None):
    o=JS(code) if show is None else show
    return S2(c_,tag,title,CODE(code,fs)+note,RES(OUT(o,26),'Kết quả chạy Node.js'))
C1="let a = [1, 2, 3];\nlet b = a.map(x => x * 2).filter(x => x > 2);\nconsole.log(b.length, b[0]);"
C2="console.log(typeof null, typeof [], typeof undefined, [] == false);"
C3="let s = '5' + 3;\nlet t = '5' - 3;\nlet u = +'5' + 3;\nconsole.log(s, t, u);"
C4="console.log([10, 9, 1, 100].sort().join(','),\n            [10, 9, 1, 100].sort((a, b) => a - b).join(','));"
C5="let r = [];\nfor (const k in { x: 1, y: 2 }) r.push(k);\nfor (const v of [3, 4]) r.push(v);\nconsole.log(r.join(' '));"
C6="const t = [1,2,3,4,5].reduce(\n  (acc, x) => x % 2 ? acc + x : acc * x, 1);\nconsole.log(t);"
C7="let x = 1;\nfunction f() {\n  console.log(x);\n  var x = 2;\n}\nf();\nconsole.log(x);"
C8="var out = [];\nfor (var i = 0; i < 3; i++) {\n  setTimeout(() => out.push(i), 0);\n}\nsetTimeout(() => console.log(out.join(',')), 10);"
