S.append(goals(c,B,['Khai báo biến <b>let, const, var</b> và hiểu <b>phạm vi</b>.','Nắm <b>kiểu dữ liệu</b>, <b>ép kiểu</b> với + và -, <b>typeof</b>.','Dùng <b>map, filter, reduce, sort</b>; phân biệt <b>for…in</b> và <b>for…of</b>.','Hiểu <b>hoisting</b> và lỗi <b>var trong vòng lặp</b>.','Dùng <b>DOM</b>: querySelector, sự kiện, <b>localStorage</b>.'],['Biến, kiểu','Mảng, hàm','Vòng lặp','Phạm vi','DOM, sự kiện']))
S.append(S2(c,B+' · 1','JavaScript làm gì trong trang web?',card('Ngôn ngữ của trình duyệt',P('<b>JavaScript (JS)</b> thêm <b>hành vi</b> cho trang: phản ứng khi bấm nút, kiểm tra biểu mẫu, đổi nội dung mà không tải lại trang.','Nhúng vào HTML bằng <b>&lt;script&gt;</b> (trong trang hoặc tệp <b>.js</b> ngoài).','Có thể chạy ngoài trình duyệt bằng <b>Node.js</b> (dùng cho các ví dụ ở đây).')),CODE('<button id="b">Bấm</button>\n<script>\n  document.getElementById("b")\n    .onclick = () => alert("Chào!");\n</script>',20)+KEY('<b>HTML</b> cấu trúc, <b>CSS</b> trình bày, <b>JavaScript</b> hành vi.')))
S.append(S2(c,B+' · 1','Khai báo biến: let, const, var',card('Ba cách',P('<b>let</b>: biến đổi được, phạm vi <b>khối</b> { }.','<b>const</b>: <b>hằng</b>, không gán lại, phạm vi khối.','<b>var</b> (cũ): phạm vi <b>hàm</b>, bị <b>hoisting</b>; nên tránh.','Kiểu: number, string, boolean, <b>null</b>, <b>undefined</b>, object, array.')),CODE('let n = 5;\nconst PI = 3.14;\nvar s = "cũ";\nn = n + 1;      // đúng\n// PI = 3;      // lỗi',22)+KEY('Dùng <b>const</b> mặc định, <b>let</b> khi cần đổi giá trị; hạn chế <b>var</b>.')))
S.append(JR(c,C2,B+' · 2','typeof và so sánh lỏng',KEY('<b>typeof null = "object"</b> (lỗi lịch sử); mảng cũng là object; <code>[] == false</code> ép kiểu thành <b>true</b>.')))
S.append(JR(c,C3,B+' · 2','Ép kiểu: + nối chuỗi, - tính số',KEY('<b>+</b> với một vế là chuỗi → <b>nối chuỗi</b>; <b>-</b> luôn ép về <b>số</b>; dấu <b>+</b> đứng trước chuỗi ép thành số.')))
S.append(S2(c,B+' · 2','So sánh == và ===',card('Lỏng và chặt',P('<b>==</b> so sánh <b>sau khi ép kiểu</b> (lỏng).','<b>===</b> so sánh <b>cả giá trị lẫn kiểu</b> (chặt) — nên dùng.')),RES(OUT(JS("console.log(5=='5', 5==='5', 0==false, 0===false, null==undefined, null===undefined)"),26),'Kết quả chạy Node.js')+CODE("5=='5'  5==='5'\n0==false  0===false\nnull==undefined  null===undefined",20)+KEY('Ưu tiên <b>===</b> để tránh kết quả bất ngờ do ép kiểu.')))
S.append(JR(c,C1,B+' · 3','Mảng: map và filter',KEY('<b>map</b> biến đổi từng phần tử: [2,4,6]; <b>filter</b> giữ phần tử thoả điều kiện: [4,6].')))
S.append(JR(c,C6,B+' · 3','reduce: gộp mảng thành một giá trị',KEY('Theo dõi <b>acc</b> từng bước: lẻ → cộng, chẵn → nhân, khởi đầu 1.')))
S.append(S2(c,B+' · 3','Theo dõi reduce từng bước',card('Từng phần tử',T(tr('x','x % 2','acc mới',h=True)+tr('1','lẻ','1 + 1 = 2')+tr('2','chẵn','2 × 2 = 4')+tr('3','lẻ','4 + 3 = 7')+tr('4','chẵn','7 × 4 = 28')+tr('5','lẻ','28 + 5 = <b>33</b>'))),RES(OUT(JS(C6),30),'Kết quả chạy Node.js')+KEY('Kết quả <b>33</b>, trùng với bảng theo dõi.')))
