S.append(JR(c,C5,B+' · 4','for…in và for…of',KEY('<b>for…in</b> duyệt <b>khoá</b> (tên thuộc tính; với mảng là chỉ số dạng chuỗi); <b>for…of</b> duyệt <b>giá trị</b>.')))
S.append(JR(c,C7,B+' · 5','Hoisting và phạm vi biến',KEY('<b>var x</b> bị kéo lên đầu hàm nhưng chưa gán → in <b>undefined</b>; x toàn cục vẫn là 1.')))
S.append(JR(c,C8,B+' · 5','var trong vòng lặp với setTimeout',KEY('<b>var</b> có phạm vi hàm: cả ba callback dùng chung một i; khi chạy i = 3 → <b>3,3,3</b>.')))
S.append(JR(c,C8b,B+' · 5','Sửa bằng let',KEY('<b>let</b> tạo biến i riêng cho mỗi vòng lặp → <b>0,1,2</b>.')))
S.append(S2(c,B+' · 6','DOM: chọn phần tử',card('Cây phần tử trong JS',P('<b>document.querySelector(selector)</b>: chọn phần tử <b>ĐẦU TIÊN</b> khớp bộ chọn CSS.','<b>querySelectorAll</b>: <b>tất cả</b> phần tử khớp.','<b>getElementById</b>: theo id.','Đổi nội dung: <b>.textContent</b>, <b>.innerHTML</b>; đổi kiểu: <b>.style</b>.')),CODE('const t = document.querySelector(".note");\nt.textContent = "Đã đổi";\nt.style.color = "red";',22)+KEY('Chọn <b>phần tử đầu tiên</b> khớp bộ chọn CSS: <b>querySelector</b>.')))
S.append(S2(c,B+' · 6','Sự kiện (event)',card('Phản ứng với người dùng',P('<b>click</b>: bấm; <b>input</b>: đang gõ; <b>change</b>: giá trị đổi <b>và rời khỏi ô</b>; <b>submit</b>: gửi biểu mẫu.','Gắn bằng <b>addEventListener</b>.')),CODE('const o = document.querySelector("input");\no.addEventListener("change", () => {\n  console.log("đã đổi:", o.value);\n});',20)+KEY('Người dùng đổi giá trị ô input <b>và rời khỏi ô</b>: sự kiện <b>change</b>.')))
S.append(S2(c,B+' · 6','localStorage: lưu dữ liệu giữa các lần mở trang',card('Lưu trong trình duyệt',P('Đối tượng <b>window.localStorage</b> (viết <b>localStorage</b>) có <b>setItem(khoá, giá trị)</b>, <b>getItem(khoá)</b>, <b>removeItem</b>.','Dữ liệu <b>còn lại</b> khi đóng trang; chỉ lưu <b>chuỗi</b>.')),CODE('localStorage.setItem("ten", "An");\nconst t = localStorage.getItem("ten");\n\n// lưu đối tượng:\nlocalStorage.setItem("d",\n   JSON.stringify({a:1}));',20)+KEY('Dữ liệu chỉ lưu <b>chuỗi</b>: dùng JSON.stringify / JSON.parse cho đối tượng.')))
S.append(SELF(c,B+' · 7','Tự kiểm tra: ép kiểu','In ra gì? <code>5 + "3"</code>, <code>"5" - 3</code>, <code>+"5" + 3</code>','console.log(5+"3", "5"-3, +"5"+3);',P('Kết quả chạy thật: <b>%s</b>.'%JS('console.log(5+"3", "5"-3, +"5"+3)'),'+ có chuỗi → nối; - → số; +"5" → số 5 rồi cộng 3.'),22))
S.append(SELF(c,B+' · 7','Tự kiểm tra: map, filter','Mảng [1,2,3].map(x=>x*2).filter(x=>x>2). Độ dài và phần tử đầu?',C1,P('Kết quả chạy thật: <b>%s</b>.'%JS(C1)),22))
S.append(SELF(c,B+' · 7','Tự kiểm tra (HSG): hoisting','Đoạn mã in ra gì?',C7,P('Kết quả chạy thật: <b>%s</b> (hai dòng).'%JS(C7).replace('\n',' / '),'var bị hoisting lên đầu hàm → undefined; x toàn cục = 1.'),20))
S.append(SELF(c,B+' · 7','Tự kiểm tra (HSG): đúng hay sai?','(a) typeof null là "object". (b) sort() sắp số đúng thứ tự số học. (c) for…of duyệt giá trị. (d) querySelector chọn tất cả phần tử khớp. (e) change xảy ra khi đổi giá trị và rời ô.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: sắp theo chuỗi.','(c) <b>Đúng</b>.','(d) <b>Sai</b>: chỉ phần tử <b>đầu tiên</b>.','(e) <b>Đúng</b>.'),20))
